CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles (id,email,full_name) VALUES (NEW.id,NEW.email,COALESCE(NEW.raw_user_meta_data->>'full_name','')) ON CONFLICT (id) DO NOTHING; INSERT INTO public.subscriptions(user_id,status,plan,trial_ends_at,current_period_start,current_period_end) VALUES (NEW.id,'trial','free',now()+interval '24 hours',now(),now()+interval '24 hours') ON CONFLICT (user_id) DO NOTHING; RETURN NEW; END; $$;
CREATE OR REPLACE FUNCTION public.is_premium_user(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role='fundador') OR EXISTS(SELECT 1 FROM public.subscriptions s WHERE s.user_id=_user_id AND s.current_period_end > now() AND ((s.plan='free' AND s.status='trial' AND s.trial_ends_at > now()) OR (s.plan IN ('premium','vitalicio') AND s.status IN ('active','canceled')) OR (s.plan='mensal' AND s.status IN ('active','canceled') AND s.payment_method='pix' AND EXISTS(SELECT 1 FROM public.pix_payment_requests r WHERE r.user_id=s.user_id AND r.plan='mensal' AND r.status='aprovado' AND r.decided_at >= s.current_period_start)))); $$;
CREATE OR REPLACE FUNCTION public.approve_pix_payment_request(_request_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE _row public.pix_payment_requests%ROWTYPE; _start timestamptz := now(); _end timestamptz; BEGIN IF auth.role()<>'service_role' AND (auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'fundador')) THEN RAISE EXCEPTION 'Ação não permitida.' USING ERRCODE='42501'; END IF; SELECT * INTO _row FROM public.pix_payment_requests WHERE id=_request_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Solicitação não encontrada.'; END IF; IF _row.status<>'aguardando_aprovacao' THEN RAISE EXCEPTION 'Esta solicitação já foi processada.'; END IF; IF _row.plan<>'mensal' THEN RAISE EXCEPTION 'Plano inválido.'; END IF; _end := _start + interval '30 days'; INSERT INTO public.subscriptions(user_id,status,plan,current_period_start,current_period_end,payment_method,trial_ends_at) VALUES(_row.user_id,'active','mensal',_start,_end,'pix',NULL) ON CONFLICT(user_id) DO UPDATE SET status='active',plan='mensal',current_period_start=_start,current_period_end=GREATEST(public.subscriptions.current_period_end,_end),payment_method='pix',trial_ends_at=NULL,canceled_at=NULL; UPDATE public.pix_payment_requests SET status='aprovado',decided_at=_start,decided_by=auth.uid() WHERE id=_request_id; RETURN jsonb_build_object('ok',true,'user_id',_row.user_id,'plan',_row.plan); END; $$;
REVOKE ALL ON FUNCTION public.approve_pix_payment_request(uuid) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.approve_pix_payment_request(uuid) TO authenticated, service_role;
CREATE POLICY "Premium required for bulletin tools" ON public.bulletins AS RESTRICTIVE FOR ALL TO authenticated USING(public.is_premium_user(auth.uid())) WITH CHECK(public.is_premium_user(auth.uid()));
CREATE POLICY "Premium required for preset tools" ON public.bulletin_presets AS RESTRICTIVE FOR ALL TO authenticated USING(public.is_premium_user(auth.uid())) WITH CHECK(public.is_premium_user(auth.uid()));